// Initialize the inventory table with tool data
document.addEventListener('DOMContentLoaded', function() {
  const inventory = new InventoryTable({
    jsonPath: 'dynamic/json/inventory-woodshop.json',
    tableId: 'inventoryTable',
    searchInputId: 'searchInput',
    statsConfig: {
      totalItems: 'total-items',
      totalQuantity: 'total-quantity',
      typeCounts: 'type-counts-container'
    },
    typeCountsConfig: {
      enabled: true,
      minCount: 10
    },
    columns: ['quantity', 'description', 'type'],
    columnHeaders: {
      quantity: 'Quantity',
      description: 'Item Description',
      type: 'Type of Tool'
    },
    onLoad: function(data) {
      console.log('Woodshop inventory loaded:', data.length, 'items');
    }
  });

  // Setup toggle button
  const toggleBtn = document.getElementById('toggle-type-counts');
  if (toggleBtn) {
    toggleBtn.addEventListener('click', function() {
      inventory.toggleTypeCounts();
    });
  }

  // Setup min count slider
  const minCountSlider = document.getElementById('min-count-slider');
  const minCountValue = document.getElementById('min-count-value');

  if (minCountSlider && minCountValue) {
    // Update display and filter on slider input
    minCountSlider.addEventListener('input', function() {
      minCountValue.textContent = this.value;
      inventory.updateMinCount(this.value);
    });
  }
});
